import oe.patch

patchsetmap = {
    "patch": oe.patch.PatchTree,
    "quilt": oe.patch.QuiltTree,
    "git": oe.patch.GitApplyTree,
}

cls = patchsetmap[d.getVar('PATCHTOOL') or 'quilt']

resolvermap = {
    "noop": oe.patch.NOOPResolver,
    "user": oe.patch.UserResolver,
}

rcls = resolvermap[d.getVar('PATCHRESOLVE') or 'user']

classes = {}

s = d.getVar('S')

os.putenv('PATH', d.getVar('PATH'))

# We must use one TMPDIR per process so that the "patch" processes
# don't generate the same temp file name.

import tempfile
process_tmpdir = tempfile.mkdtemp()
os.environ['TMPDIR'] = process_tmpdir

for patch in src_patches(d):
    _, _, local, _, _, parm = bb.fetch.decodeurl(patch)

    if "patchdir" in parm:
        patchdir = parm["patchdir"]
        if not os.path.isabs(patchdir):
            patchdir = os.path.join(s, patchdir)
        if not os.path.isdir(patchdir):
            bb.fatal("Target directory '%s' not found, patchdir '%s' is incorrect in patch file '%s'" %
                (patchdir, parm["patchdir"], parm['patchname']))
    else:
        patchdir = s

    if not patchdir in classes:
        patchset = cls(patchdir, d)
        resolver = rcls(patchset, oe_terminal)
        classes[patchdir] = (patchset, resolver)
        patchset.Clean()
    else:
        patchset, resolver = classes[patchdir]

    bb.note("Applying patch '%s' (%s)" % (parm['patchname'], oe.path.format_display(local, d)))
    try:
        patchset.Import({"file":local, "strippath": parm['striplevel']}, True)
    except Exception as exc:
        bb.utils.remove(process_tmpdir, True)
        bb.fatal("Importing patch '%s' with striplevel '%s'\n%s" % (local, parm['striplevel'], repr(exc).replace("\\n", "\n")))
    try:
        resolver.Resolve()
    except bb.BBHandledException as e:
        bb.utils.remove(process_tmpdir, True)
        bb.fatal("Applying patch '%s' on target directory '%s'\n%s" % (local, patchdir, repr(e).replace("\\n", "\n")))

bb.utils.remove(process_tmpdir, True)
del os.environ['TMPDIR']

